import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 1000000007;
    static int n;
    static int[][] a = new int[10][10];
    static int[][] ch = new int[70010][128];
    static int id_counter = 0;
    static int[][] q_array = new int[10][128];
    static int[][] dp_array = new int[10][70010];
    static Map<BitSet, Integer> id_map = new HashMap<>();

    static int sum(int a, int b) {
        a += b;
        if (a >= MOD) a -= MOD;
        return a;
    }

    static int product(int a, int b) {
        long res = 1L * a * b;
        if (res >= MOD) res %= MOD;
        return (int) res;
    }

    static int difference(int a, int b) {
        a -= b;
        if (a < 0) a += MOD;
        return a;
    }

    static int pow_mod(int base, int exp) {
        int res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = product(res, base);
            base = product(base, base);
            exp >>= 1;
        }
        return res;
    }

    static int get_bit(int x) {
        return x & (-x);
    }

    static int dfs_bitset(BitSet s) {
        if (id_map.containsKey(s)) return id_map.get(s);
        id_map.put(s, ++id_counter);
        for (int i = 0; i < (1 << n); i++) {
            BitSet tmp = (BitSet) s.clone();
            for (int j = 0; j < (1 << n); j++) {
                if (!tmp.get(j)) {
                    int x = i & j;
                    while (x != 0) {
                        int t = get_bit(x);
                        if (s.get(j ^ (int)(Math.log(t)/Math.log(2)))) {
                            tmp.set(j);
                            break;
                        }
                        x -= t;
                    }
                }
            }
            ch[id_map.get(s)][i] = dfs_bitset(tmp);
        }
        return id_map.get(s);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine().trim());
        BitSet initialSet = new BitSet(128);
        initialSet.set(0, 128);
        dfs_bitset(initialSet);
        for (int i = 0; i < n; i++) {
            String[] parts = br.readLine().trim().split("\\s+");
            for (int j = 0; j < n; j++) {
                a[i][j] = product(Integer.parseInt(parts[j]), pow_mod(100, MOD - 2));
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < (1 << n); j++) {
                q_array[i][j] = 1;
                for (int k = 0; k < n; k++) {
                    if (((j >> k) & 1) == 1) {
                        q_array[i][j] = product(q_array[i][j], a[i][k]);
                    } else {
                        q_array[i][j] = product(q_array[i][j], difference(1, a[i][k]));
                    }
                }
            }
        }
        for (int i = 0; i <= n; i++) {
            Arrays.fill(dp_array[i], 0);
        }
        dp_array[0][1] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= id_counter; j++) {
                for (int k = 0; k < (1 << n); k++) {
                    int index = ch[j][k];
                    dp_array[i][index] = sum(dp_array[i][index], product(dp_array[i - 1][j], q_array[i - 1][k]));
                }
            }
        }
        BitSet bits = new BitSet(128);
        bits.set(0, 128);
        int result = dp_array[n][id_map.get(bits)];
        System.out.println(result);
    }
}
